104	    if ($LASTEXITCODE -eq 0) { "search: OK" } else { "search: FAIL -> $out"; $fail += "memsearch-run" }
105	}
106	if ($onWindows) {
107	    # On the laptop memsearch talks to Milvus in Docker Desktop (WSL2). With Docker down,
108	    # every memsearch hook times out and the search above fails with an unhelpful error,
109	    # so name the real cause.
110	    $st = & docker ps --filter "name=milvus-standalone" --format "{{.Status}}" 2>&1
111	    if ($LASTEXITCODE -ne 0) { "milvus: Docker not reachable - start Docker Desktop"; $fail += "milvus-docker" }
112	    elseif ("$st" -match '\(healthy\)') { "milvus: $st" }
113	    else { "milvus: NOT HEALTHY ('$st')"; $fail += "milvus-down" }
114	}
115	
116	Section "Recall coverage"
117	# Every configured index root must exist on this machine, or it is silently never indexed.
118	# The {VAULT} bug (2026-09-30) hid ~1,370 vault notes from Windows search for weeks this way.
119	# The other machine's Tier A slug is the one expected absence.
120	$devRoot = @("$HOME/DEV", "$HOME/Desktop/DEV") | Where-Object { Test-Path "$_/KeystoneOS" } | Select-Object -First 1
121	$vaultRoot = @("$HOME/SecondBrain", "$HOME/Desktop/SecondBrain") | Where-Object { Test-Path $_ } | Select-Object -First 1
122	$idxCfg = "$devRoot/KeystoneOS/data/memory-index-paths.json"
123	if (-not (Test-Path $idxCfg)) { "index config: MISSING ($idxCfg)"; $fail += "recall-coverage" }
124	else {
125	    $otherSlug = if ($onWindows) { '-Users-kristinarash-' } else { 'C--Users-eric-rash' }
126	    $idxPaths = @((Get-Content -Raw $idxCfg | ConvertFrom-Json).paths | ForEach-Object {
127	        (($_ -replace '\{HOME\}', $HOME) -replace '\{DEV\}', $devRoot) -replace '\{VAULT\}', $vaultRoot })
128	    # Codex on the Mac keeps memories in ~/.codex/memories_1.sqlite, not a folder (2026-10-06).
129	    $notHere = if ($onWindows) { $otherSlug } else { "$otherSlug|\.codex/memories$" }
130	    $gone = @($idxPaths | Where-Object { -not (Test-Path -LiteralPath $_) -and $_ -notmatch $notHere })
131	    if ($gone.Count) { "roots: $($gone.Count) MISSING -> $($gone -join '; ')"; $fail += "recall-coverage" }
132	    else { "roots: all $($idxPaths.Count) resolve (other machine's slug excepted)" }
133	}
134	# Recall eval ledger (audits/recall-eval): flag a drop of 2+ hit@5 between this machine's
135	# last two runs of the same backend. The eval itself is run by hand or after a reindex.
136	$ledger = "$HOME/.claude/audits/recall-eval/ledger.md"
137	if (Test-Path $ledger) {
138	    $me = [System.Net.Dns]::GetHostName().ToLower()
139	    $rows = @(Get-Content $ledger | Where-Object { $_ -match '^\| \d{4}-' } | ForEach-Object {
140	        $c = $_.Trim('|').Split('|') | ForEach-Object { $_.Trim() }

140	        $c = $_.Trim('|').Split('|') | ForEach-Object { $_.Trim() }
141	        [pscustomobject]@{ Date = $c[0]; Machine = $c[1]; Backend = $c[3]; Hit5 = [int]$c[6] } } | Where-Object { $_.Machine -eq $me })
142	    foreach ($g in ($rows | Group-Object Backend)) {
143	        $last = $g.Group | Select-Object -Last 2
144	        $latest = $last[-1]
145	        if ($last.Count -eq 2 -and ($last[0].Hit5 - $latest.Hit5) -ge 2) {
146	            "eval $($g.Name): hit@5 fell $($last[0].Hit5) -> $($latest.Hit5) ($($latest.Date))"; $fail += "recall-regress"
147	        } else { "eval $($g.Name): hit@5 $($latest.Hit5) ($($latest.Date))" }
148	    }
149	} else { "eval: no ledger yet (python ~/.claude/audits/recall-eval/recall-eval.py)" }
150	
151	Section "Memory pipeline"
152	$errlog = "$HOME/.claude/global-memory/transcripts/.errors.log"
153	if ((Test-Path $errlog) -and ((Get-Item -Force $errlog).Length -gt 0)) {
154	    "errors.log: NON-EMPTY (hook failures below)"; Get-Content $errlog -Tail 5; $fail += "errors-log"
155	} else { "errors.log: clean" }
156	
157	$lastFlush = "$HOME/.claude/claude-memory-compiler/scripts/last-flush.json"
158	if (Test-Path $lastFlush) {
159	    $ageH = (New-TimeSpan -Start (Get-Item $lastFlush).LastWriteTime -End (Get-Date)).TotalHours
160	    if ($ageH -gt 48) { "last-flush.json: STALE ($([math]::Round($ageH))h old)"; $fail += "flush-stale" }
161	    else { "last-flush.json: OK ($([math]::Round($ageH))h ago)" }
162	} else { "last-flush.json: MISSING"; $fail += "flush-missing" }
163	
164	$daily = "$HOME/.claude/claude-memory-compiler\daily"
165	$recent = Get-ChildItem $daily -Filter '*.md' -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 3
166	$flushErr = $recent | Select-String -Pattern 'FLUSH_ERROR' | Select-Object -First 3
167	if ($flushErr) {
168	    "FLUSH_ERROR in recent dailies:"; $flushErr | ForEach-Object { "  $($_.Filename):$($_.LineNumber)" }
169	    $fail += "flush-error"
170	} else { "recent dailies (3): no FLUSH_ERROR" }
171	
172	Section "Backup freshness"
173	$bkState = "$HOME/.claude/scripts/logs/backup-state.json"
174	if ($onWindows) {
175	    # daily-backup.ps1 (backup-state.json) is the Mac's job. The laptop's own backup job
176	    # (backup-ai-sessions.ps1) was disabled 2026-10-08 and removed 2026-10-23: the Mac's daily
177	    # backup snapshots .claude/projects and .codex. Desktop\DEV is a Drive for Desktop synced root.
178	    "windows: no backup job here since 2026-10-08 (the Mac's daily backup covers it) - nothing to check"
179	} elseif (-not (Test-Path $bkState)) { "backup-state.json: MISSING (daily-backup has never run?)"; $fail += "backup-missing" }
180	else {
181	    $bk = Get-Content $bkState -Raw | ConvertFrom-Json
182	    $ageH = (New-TimeSpan -Start ([datetime]$bk.lastRun) -End (Get-Date)).TotalHours
183	    # daily-backup.ps1 writes backup-state.json even under -DryRun. A dry run copies
184	    # nothing, so a dry-run "OK" must never be read as a healthy backup - doing so
185	    # masks the last REAL run's failure. Observed 2026-08-14: a diagnostic dry run at
186	    # 20:54 overwrote the 20:38 real-run ERROR and cleared backup-error from this
187	    # VERDICT while nothing had actually been backed up since the failure.
188	    # dryRun is a MODIFIER, not a branch: a dry run can also be stale or errored, and an
189	    # earlier version that returned early on dryRun would report a 40h-old dry run without
190	    # ever raising backup-stale. Keep the signals independent so every true condition fires.
191	    # ($bk.dryRun is $null on state files predating the field, which is falsy - correct.)
192	    $mode = if ($bk.dryRun) { ' [DRY RUN - nothing was copied]' } else { '' }
193	    if ($bk.dryRun) { $fail += "backup-dryrun-only" }
194	    $h = [math]::Round($ageH)
195	    if ($ageH -gt 30) { "last backup: STALE (${h}h ago)$mode"; $fail += "backup-stale" }
196	    elseif ($bk.status -ne 'OK') { "last backup: ERROR ($($bk.errors -join ', '))$mode"; $fail += "backup-error" }
197	    else { "last backup: OK (${h}h ago, $($bk.okCount) targets)$mode" }
198	}
199	$bkRepos = @(
200	    @{ p = "$HOME/SecondBrain"; b = 'main' },
201	    @{ p = "$HOME/.claude/global-memory"; b = 'main' },
202	    @{ p = "$HOME/.claude"; b = 'main' },
203	    @{ p = "$HOME/.claude/skills"; b = 'main' }
204	)
205	foreach ($r in $bkRepos) {
206	    # SecondBrain is Mac-only; its absence on the laptop is correct (as in handoff-check).
207	    if ($onWindows -and -not (Test-Path $r.p)) { "$(Split-Path $r.p -Leaf) : not on this machine (skipped)"; continue }
208	    if (-not (Test-Path (Join-Path $r.p '.git'))) { "$($r.p): NOT A REPO"; $fail += "backup-repo-gone"; continue }
209	    Push-Location $r.p
210	    $counts = git rev-list --left-right --count "origin/$($r.b)...HEAD" 2>$null
211	    $ahead = if ($counts) { [int](($counts -split '\s+')[1]) } else { 0 }
212	    $name = Split-Path $r.p -Leaf
213	    if ($ahead -gt 3) { "$name : $ahead unpushed commit(s) - pushes may be failing"; $fail += "backup-repo-drift:$name" }
214	    else { "$name : synced (ahead=$ahead)" }
215	    Pop-Location
216	}
217	
218	# Cloud-side verification: rsync proves files reached the local DriveFS cache, not that
219	# Google's servers have them. The per-run receipts (_receipts/run-<id>.txt) are written
220	# with fresh content every run, so the newest one's Drive-side modifiedTime is a heartbeat
221	# for the whole DriveFS sync path.
222	#
223	# Was RESTORE.md until 2026-08-14. That was a false-positive generator: the job *copies*
224	# RESTORE.md (Copy-Item -Force, daily-backup.ps1:411) rather than rewriting it, so the
225	# copy carries the source's mtime. RESTORE.md hadn't changed since 2026-08-05, so this
226	# check reported "STALE (218h)" and "DriveFS sync may be broken" while sync was in fact
227	# healthy — the receipt written 07:23 CDT was on Google's servers at 12:23:54Z, matching
228	# the local mtime to the second.
229	$gwsCmd = Get-Command gws -ErrorAction SilentlyContinue
230	if ($gwsCmd) {
231	    $q = '{"q":"name contains ''run-2'' and trashed = false","orderBy":"modifiedTime desc","fields":"files(name,modifiedTime)","pageSize":20}'
232	    $out = & gws drive files list --params $q 2>&1
233	    if ($LASTEXITCODE -ne 0) {
234	        "cloud check: gws Drive query FAILED (auth rot? re-run: gws auth login --scopes drive.readonly,calendar.readonly full URLs)"
235	        $fail += "backup-cloud-check"
236	    } else {
237	        $j = (($out | Where-Object { $_ -notmatch '^Using keyring' }) -join "`n") | ConvertFrom-Json
238	        # ConvertFrom-Json may hand back a DateTime (kind varies) or a raw string;
239	        # normalize to UTC either way — naive local comparison produced "-4h" ages.
240	        # Drive's `name contains 'run-2'` is token matching, not substring: on 2026-09-22 it
241	        # returned an unrelated jev_run2.jsonl as the newest hit, and a fresh unrelated
242	        # file would mask a stale backup. Keep only real receipts.
243	        $mt = $j.files | Where-Object { $_.name -like 'run-*.txt' } | ForEach-Object {
244	            $v = $_.modifiedTime
245	            if ($v -is [datetime]) { $v.ToUniversalTime() } else { ([DateTimeOffset]::Parse($v)).UtcDateTime }
246	        } | Sort-Object -Descending | Select-Object -First 1
247	        if (-not $mt) { "cloud check: no backup receipt found in Drive"; $fail += "backup-cloud-missing" }
248	        else {
249	            $ageH = ((Get-Date).ToUniversalTime() - $mt).TotalHours
250	            if ($ageH -gt 48) { "cloud check: newest Drive-side receipt STALE ($([math]::Round($ageH))h old) - DriveFS sync may be broken"; $fail += "backup-cloud-stale" }
251	            else { "cloud check: Google's servers have the latest backup receipt ($([math]::Round($ageH))h old) - sync path verified" }
252	        }
253	    }
254	} else { "cloud check: gws CLI not installed (skipped)" }
255	
256	Section "Context budget"
257	# Skill descriptions are preloaded into EVERY session, so this is a per-session
258	# tax paid whether or not a skill fires. It regrows silently: the 2026-07-13
259	# skill audit pruned the set, and by 2026-07-24 it was back to 105 skills /
260	# 42,885 chars (~10,700 tokens). Archiving 45 dead/dormant skills brought it to
261	# ~27,000. A number nobody watches is a number that drifts, so watch it.
262	$skillRoot = "$HOME/.claude/skills"
263	# A skill set to "off" in settings.json's skillOverrides is NOT loaded into the
264	# session listing, so it costs zero context and must not be counted. Before
265	# 2026-08-11 this loop counted every SKILL.md on disk, which reported 133 skills
266	# / 65,467 chars as OVER budget while 72 of them were already disabled — a false
267	# positive that fired every weekly run and spammed .errors.log. Read only the
268	# skillOverrides key; settings.json also holds env/secrets.
269	$off = @{}
270	$settingsPath = "$HOME/.claude/settings.json"
271	if (Test-Path $settingsPath) {
272	    try {
273	        $so = (Get-Content $settingsPath -Raw | ConvertFrom-Json).skillOverrides
274	        if ($so) {
275	            foreach ($p in $so.PSObject.Properties) {
276	                if ($p.Value -eq 'off') { $off[$p.Name] = $true }
277	            }
278	        }
279	    } catch { }
280	}
281	$descChars = 0; $skillCount = 0; $offCount = 0
282	foreach ($d in Get-ChildItem $skillRoot -Directory -ErrorAction SilentlyContinue) {
283	    $sk = Join-Path $d.FullName 'SKILL.md'
284	    if (-not (Test-Path $sk)) { continue }
285	    if ($off.ContainsKey($d.Name)) { $offCount++; continue }
286	    $raw = Get-Content $sk -Raw
287	    if ($raw -match '(?s)description:\s*(.*?)(\n[a-z-]+:|\n---)') {
288	        $descChars += (($Matches[1] -replace '\s+', ' ').Trim()).Length
289	        $skillCount++
290	    }
291	}
292	if ($offCount) { "skill overrides: $offCount skill(s) disabled in settings.json - excluded from tax" }
293	$budget = 32000
294	$pct = if ($budget) { [math]::Round(100 * $descChars / $budget) } else { 0 }
295	if ($descChars -gt $budget) {
296	    "skill tax: $skillCount skills, $descChars chars (~$([math]::Round($descChars/4)) tokens) - OVER budget $budget ($pct%)"
297	    "  -> archive unused skills to ~/.claude/skills-archive, or trim descriptions to trigger conditions only"
298	    $fail += "skill-tax"
299	} else {
300	    "skill tax: $skillCount skills, $descChars chars (~$([math]::Round($descChars/4)) tokens) - OK ($pct% of $budget)"
301	}
302	
303	# Both files are loaded every session and both have caps declared in CLAUDE.md.
304	# At >95% the next write is a forced consolidation, and consolidations made
305	# under pressure drop facts quietly. Flag before it gets there, not after.
306	foreach ($m in @(
307	    @{ f = "$HOME/.claude/global-memory\USER.md";   cap = 1375 },
308	    @{ f = "$HOME/.claude/global-memory\MEMORY.md"; cap = 2500 })) {
309	    $n = Split-Path $m.f -Leaf
310	    if (-not (Test-Path $m.f)) { "$n : MISSING"; $fail += "memfile-missing:$n"; continue }
311	    $len = (Get-Item $m.f).Length
312	    $p = [math]::Round(100 * $len / $m.cap)
313	    if ($p -ge 95) { "$n : $len/$($m.cap) chars ($p%) - NO HEADROOM, consolidate deliberately before the next write forces it"; $fail += "memfile-full:$n" }
314	    else { "$n : $len/$($m.cap) chars ($p%) - OK" }
315	}
316	
317	if (-not $onWindows) {
318	Section "Job proof (logs, not exit codes)"
319	# A launchd exit code of 0 is not proof the job did its work: Meeting Sync failed on every
320	# scheduled run from 08-06 to 10-23 ("not authenticated") while the cadence still logged OK.
321	# These read each job's own log for the line that only real success writes.
322	# maxH allows for a weekend with the lid shut.
323	$maxH = 50
324	# PROOF_* env vars point the checks at fixture logs (test-job-proof.sh).
325	$cad = if ($env:PROOF_CADENCE_LOG) { $env:PROOF_CADENCE_LOG } else { "$HOME/DEV/KeystoneOS/outputs/morning/cadence.log" }
326	if (Test-Path $cad) {
327	    $lines = @(Get-Content $cad -Tail 400)
328	    $start = ($lines | Select-String -Pattern '^== Meeting Sync ==' | Select-Object -Last 1).LineNumber
329	    if (-not $start) { "meeting-sync: no block in the last 400 lines"; $fail += "proof:meeting-sync" }
330	    else {
331	        # The block runs to the next "== " header; the run's time is on the
332	        # "[stamp] cadence ..." line that ends the run, after the block.
333	        $block = @(); $when = $null; $done = $false
334	        foreach ($l in $lines[$start..($lines.Count - 1)]) {
335	            if ($l -match '^\[(\S+)\] cadence') { $when = [datetime]$Matches[1]; break }
336	            if (-not $done) { if ($l -match '^== ') { $done = $true } else { $block += $l } }
337	        }
338	        $ageH = if ($when) { [math]::Round(((Get-Date) - $when).TotalHours) } else { 999 }
339	        if (-not ($block -match 'sync_complete')) { "meeting-sync: FAIL -> $($block | Select-Object -First 1)"; $fail += "proof:meeting-sync" }
340	        elseif ($ageH -gt $maxH) { "meeting-sync: last good run ${ageH}h ago - STALE"; $fail += "proof:meeting-sync-stale" }
341	        else { "meeting-sync: OK sync_complete (${ageH}h ago)" }
342	    }
343	} else { "meeting-sync: cadence.log MISSING"; $fail += "proof:meeting-sync" }
344	
345	foreach ($p in @(
346	    @{ n = 'backup-harvest'; f = $(if ($env:PROOF_BACKUP_LOG) { $env:PROOF_BACKUP_LOG } else { "$HOME/.claude/scripts/logs/daily-backup.log" });  rx = '^(\S+ \S+) HARVEST harvested' },
347	    @{ n = 'nightly-digest'; f = $(if ($env:PROOF_DIGEST_LOG) { $env:PROOF_DIGEST_LOG } else { "$HOME/.claude/scripts/logs/nightly-digest.log" }); rx = '^\[(\S+)\] sent ' })) {
348	    if (-not (Test-Path $p.f)) { "$($p.n): log MISSING"; $fail += "proof:$($p.n)"; continue }
349	    $hit = Get-Content $p.f -Tail 2000 | Select-String -Pattern $p.rx | Select-Object -Last 1
350	    if (-not $hit) { "$($p.n): no success line in the log"; $fail += "proof:$($p.n)"; continue }
351	    $ageH = [math]::Round(((Get-Date) - [datetime]$hit.Matches[0].Groups[1].Value).TotalHours)
352	    if ($ageH -gt $maxH) { "$($p.n): last success ${ageH}h ago - STALE"; $fail += "proof:$($p.n)" }
353	    else { "$($p.n): OK (${ageH}h ago)" }
354	}
355	}
356	
357	# Cross-machine handoff. Lives in its own script because it is the one check that
358	# must also run on the Windows laptop, where the launchd section above cannot. The
359	# backup section measures `ahead` and so catches a failing push; this catches the
360	# opposite and previously invisible failure, a push that succeeded and a pull that
361	# never happened.
362	$handoff = Join-Path $PSScriptRoot 'handoff-check.ps1'
363	if (Test-Path $handoff) {
364	    & $handoff
365	    if ($LASTEXITCODE -ne 0) { $fail += "handoff" }
366	} else {
367	    "`n=== Cross-machine handoff ===`nhandoff-check.ps1: MISSING"
368	    $fail += "handoff-check-missing"
369	}
370	
371	Section "VERDICT"
372	if ($fail.Count -eq 0) { "ALL CLEAR" } else { "$($fail.Count) issue(s): $($fail -join ', ')" }
373	exit [int]($fail.Count -gt 0)

