Section "PowerShell runtime"
# Every launchd .ps1 job (and the daily backup via daily-backup-login.sh) runs
# /opt/homebrew/bin/pwsh. It was installed from the powershell/tap formula, which Homebrew
# deprecated 2026-06-18 and disables 2027-06-18 (brew info powershell/tap/powershell).
# The swap needs Eric at the machine, so this only informs until PWSH_TAP_FAIL_FROM
# (default 2027-03-01, env override for test-pwsh-tap.sh) and fails the weekly run after.
# Reads the keg's INSTALL_RECEIPT.json: no brew process, no network.
$pwshFailFrom = [datetime]$(if ($env:PWSH_TAP_FAIL_FROM) { $env:PWSH_TAP_FAIL_FROM } else { '2027-03-01' })
$pwshItem = Get-Item '/opt/homebrew/bin/pwsh' -ErrorAction SilentlyContinue
if (-not $pwshItem) { "pwsh: /opt/homebrew/bin/pwsh MISSING - the launchd .ps1 jobs cannot start" }
else {
