input.command:
build="${TMPDIR:-/tmp}/five-slides"; mkdir -p "$build"; echo "build=$build"; cat > "$build/deck.js" <<'EOF'
const pptxgen = require("pptxgenjs");
async function buildDeck() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.title = "Mac export test - 5 Slides in 5 Minutes";
  const PRIMARY = "0D1B2A", ACCENT = "00B4D8", WHITE = "FFFFFF", LIGHT_BG = "EEF4F7", MUTED = "A0B8C0";
  for (let n = 1; n <= 3; n++) {
    const dark = n % 2 === 1;
    const s = pres.addSlide();
    s.background = { color: dark ? PRIMARY : LIGHT_BG };
    if (dark) s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.18, h: 5.625, fill: { color: ACCENT }, line: { color: ACCENT } });
    s.addText("5 SLIDES · 5 MINUTES", { x: 0.38, y: 0.28, w: 9, h: 0.35, fontSize: 10, color: ACCENT, bold: true, charSpacing: 4, margin: 0 });
    s.addText("MAC EXPORT TEST", { x: 0.38, y: 0.28, w: 9.4, h: 0.35, fontSize: 10, color: ACCENT, bold: true, charSpacing: 4, align: "right", margin: 0 });
    s.addText(`Test slide ${n}`, { x: 0.38, y: 1.6, w: 9, h: 1.2, fontSize: 48, bold: true, color: dark ? WHITE : PRIMARY, fontFace: "Arial Black", margin: 0 });
    s.addText("Baylor Athletics · Applied Performance", { x: 0.38, y: 5.1, w: 9.4, h: 0.5, fontSize: 11, color: MUTED, italic: true, margin: 0 });
    s.addText(`Slide ${n} of 3`, { x: 0.38, y: 5.1, w: 9.4, h: 0.5, fontSize: 11, color: MUTED, align: "right", margin: 0 });
  }
  await pres.writeFile({ fileName: "deck.pptx" });
  console.log("Deck created successfully");
}
buildDeck().catch(console.error);
EOF
cd "$build" && perl -e 'alarm 180; exec @ARGV' npm install pptxgenjs 2>/dev/null | tail -3; node deck.js; ls -la "$build"/deck.pptx

